# -*- coding: utf-8 -*-
"""Contenido del manuscrito para en-LISOS. Las citas van entre dobles llaves con el PMID o una clave de EXTRA."""

TITULO = 'Inteligencia artificial en las enfermedades de depósito lisosomal: qué está demostrado, qué es prometedor y qué falta para llegar a la práctica clínica'
TITLE_EN = 'Artificial intelligence in lysosomal storage disorders: what is proven, what is promising and what is still missing before clinical implementation'
TITULO_CORTO = 'Inteligencia artificial en las enfermedades lisosomales'

RESUMEN = [
    ('Objetivo', 'Revisar de forma crítica las aplicaciones de la inteligencia artificial (IA) en las enfermedades de depósito lisosomal y explicar por qué es difícil desarrollar modelos fiables en enfermedades de baja prevalencia.'),
    ('Métodos', 'Revisión narrativa con búsqueda estructurada en PubMed, Europe PMC y ClinicalTrials.gov hasta el 16 de noviembre de 2026, sin acceso a Embase, Scopus ni Web of Science. Se distinguió entre evidencia directa en enfermedades lisosomales, evidencia complementaria de otras enfermedades raras y aplicaciones potenciales.'),
    ('Resultados', 'Se identificaron 59 estudios originales en enfermedades lisosomales. Las aplicaciones más estudiadas son la búsqueda de casos en datos asistenciales (Gaucher, Fabry, Pompe y mucopolisacaridosis) y la medición automática en imagen y patología digital. Casi todos son retrospectivos, incluyen decenas de pacientes y solo tienen validación interna: cuatro se probaron con datos externos y ninguno midió su efecto sobre la atención. No se encontraron modelos validados de respuesta al tratamiento ni estudios con grandes modelos de lenguaje en pacientes. La escasez de casos, la heterogeneidad clínica y genética, la distribución geográfica desigual, el desequilibrio entre enfermos y sanos, la fragmentación de los datos y la falta de validación externa explican buena parte de estas limitaciones.'),
    ('Conclusiones', 'La IA es hoy, en las enfermedades lisosomales, una herramienta de investigación prometedora, más madura para medir que para diagnosticar. Su llegada a la práctica clínica exige colaboración multicéntrica, datos armonizados y validación externa y prospectiva.'),
]
PALABRAS_CLAVE = 'Inteligencia Artificial; Aprendizaje Automático; Aprendizaje Profundo; Enfermedades por Almacenamiento Lisosomal; Enfermedades Raras; Diagnóstico Precoz.'
ABSTRACT = [
    ('Objective', 'To critically review the applications of artificial intelligence (AI) in lysosomal storage disorders and to explain why reliable models are hard to develop in low-prevalence diseases.'),
    ('Methods', 'Narrative review with a structured search of PubMed, Europe PMC and ClinicalTrials.gov up to 16 November 2026, without access to Embase, Scopus or Web of Science. Direct evidence in lysosomal disorders, complementary evidence from other rare diseases and potential applications were kept separate.'),
    ('Results', 'Fifty-nine original studies in lysosomal disorders were identified. The most studied applications are case finding in healthcare data (Gaucher, Fabry, Pompe and mucopolysaccharidoses) and automated measurement in imaging and digital pathology. Almost all are retrospective, include tens of patients and rely on internal validation only: four were tested on external data and none measured its effect on care. No validated model of treatment response and no study of large language models in patients were found. Scarcity of cases, clinical and genetic heterogeneity, uneven geographic distribution, class imbalance, data fragmentation and lack of external validation account for much of these limitations.'),
    ('Conclusions', 'In lysosomal disorders, AI is currently a promising research tool, more mature for measuring than for diagnosing. Reaching clinical practice requires multicentre collaboration, harmonised data and external and prospective validation.'),
]
KEYWORDS = 'Artificial Intelligence; Machine Learning; Deep Learning; Lysosomal Storage Diseases; Rare Diseases; Early Diagnosis.'

# ----------------------------------------------------------------------------- cuerpo
INTRO = [
    'Las enfermedades de depósito lisosomal (EDL) son más de 70 trastornos hereditarios causados por el mal funcionamiento del lisosoma. Cada una es rara, pero en conjunto afectan a 1 de cada 5.000 nacidos vivos {{30275469}}. Son progresivas, multisistémicas y muy variables, y varias tienen tratamiento específico {{30275469}}.',
    'El diagnóstico suele llegar tarde. En la enfermedad de Gaucher transcurren de media unos cuatro años entre los primeros síntomas y el diagnóstico, con complicaciones que podrían haberse evitado {{17492645}}. En adultos con enfermedad de Fabry la mediana supera los diez años {{28097762}}, y en la enfermedad de Pompe alcanza 12,6 años en las formas infantiles sin miocardiopatía y en las juveniles {{23997011}}.',
    'La inteligencia artificial (IA) se ha propuesto para acortar ese recorrido, medir mejor la afectación de los órganos y anticipar la evolución, y ya existen revisiones generales sobre el tema {{41661224,40247315}}. Esta revisión tiene dos objetivos: describir qué aplicaciones se han estudiado en las EDL y con qué solidez, y explicar por qué desarrollar modelos fiables es especialmente difícil en enfermedades de baja prevalencia.',
    'Se buscó en PubMed/MEDLINE, Europe PMC (incluidos preprints) y ClinicalTrials.gov hasta el 16 de noviembre de 2026; sin acceso a Embase, Scopus ni Web of Science, la búsqueda no es exhaustiva. Se priorizaron los textos completos en acceso abierto. Se distingue entre evidencia directa (estudios en EDL), complementaria (otras enfermedades raras) y aplicaciones potenciales.',
]

DESARROLLO = [
 ('Qué es y qué no es la inteligencia artificial', [
    '«Inteligencia artificial» es un término paraguas. El aprendizaje automático (*machine learning*) agrupa los algoritmos que, en lugar de seguir reglas escritas por un experto, aprenden patrones a partir de ejemplos, como un residente aprende a reconocer una enfermedad viendo muchos casos. El aprendizaje profundo (*deep learning*) usa redes neuronales de muchas capas y es el método habitual para imágenes y señales. El procesamiento del lenguaje natural extrae información del texto libre, y los grandes modelos de lenguaje generan texto {{30943338}}.',
    'No todo lo que se publica como IA lo es. La regresión logística, el análisis discriminante, las puntuaciones por reglas o el agrupamiento (*clustering*) son estadística convencional, igualmente válida. Un modelo más complejo no es necesariamente mejor: en varones con enfermedad de Fabry clásica, una regresión logística de tres variables predijo la aparición de anticuerpos frente a la enzima igual que un *random forest*, con un área bajo la curva (AUC) de 0,77 en ambos casos {{32806627}}, y una revisión sistemática de 71 estudios no halló ventaja del aprendizaje automático sobre la regresión logística {{30763612}}.',
    'Dos ideas ayudan a leer estos estudios (figura 1). Un modelo se *entrena* con casos conocidos y debe *validarse* con pacientes que no ha visto, primero del mismo centro y luego de otros. Y el AUC, la medida más usada, es la probabilidad de que el modelo asigne más riesgo a un enfermo que a un sano elegidos al azar (0,5 equivale al azar; 1, a la separación perfecta), pero no dice cuántos de los señalados están realmente enfermos.',
 ]),
 ('Detección y diagnóstico precoz', [
    'La aplicación más estudiada es la búsqueda de pacientes no diagnosticados en datos asistenciales (tabla 1){{T1}}. En la enfermedad de Gaucher, un modelo entrenado con historias y reclamaciones de Estados Unidos redujo de 20.743 a 1.204 las personas que habría que revisar para localizar a 28 pacientes ya diagnosticados {{37689674}}, y otro los identificó una mediana de 2,78 años antes del diagnóstico real {{39245415}}. En la enfermedad de Fabry hay un modelo con casi 5.000 pacientes {{34930374}}, una puntuación de regresión logística penalizada {{38187171}} y un sistema de lenguaje natural con puntuación por reglas cuyo AUC de 0,998 se calculó con los mismos 13 casos usados para diseñarlo {{37240705}}. En la enfermedad de Pompe, una herramienta comercial señaló 104 historias entre 350.116; 19 resultaron clínicamente plausibles, sin confirmación enzimática ni genética {{37153672}}. En las mucopolisacaridosis (MPS), dos trabajos con los mismos 37 pacientes pediátricos comunicaron AUC de 0,96 y 0,97 {{40770294,41593722}}, y un clasificador de MPS II para atención primaria se entrenó con casos creados artificialmente {{30566525}}.',
    'Todos son retrospectivos, con validación interna, y ninguno ha demostrado que acorte el diagnóstico; en Gaucher hay registrado un estudio de implementación {{NCT05908656}}. El diseño de referencia procede de otra enfermedad rara: en la inmunodeficiencia variable común, un algoritmo se validó en más de seis millones de historias de otros sistemas sanitarios {{38691621}}.',
    'El reconocimiento facial se ha explorado en la enfermedad de Gaucher neuronopática {{34663554}}, la mucolipidosis IV {{32298796}} y las MPS {{29623569}}, con pocas decenas de pacientes. En el cribado neonatal, herramientas de reconocimiento de patrones que no son aprendizaje automático en sentido estricto redujeron de 48 a 10 las derivaciones anuales por sospecha de enfermedad de Krabbe en Nueva York {{33239591}} y se han aplicado a Pompe y a MPS I {{32064362}}.',
 ]),
 ('Imagen médica y patología digital', [
    'El uso más maduro de la IA en imagen es medir de forma automática lo que hoy se mide a mano. Una red neuronal estimó el volumen del bazo en la enfermedad de Gaucher con un error del 3,6 %, frente al 13,9 % de la fórmula habitual {{37629403}}; otra cuantificó la desmielinización en la leucodistrofia metacromática con buena concordancia en una cohorte de prueba independiente {{42012644}}; y una herramienta general de edad ósea mantuvo un error medio de 7 meses en radiografías de niños con MPS y alfa-manosidosis {{41727682}}. También se han cuantificado la osteonecrosis en Gaucher {{38834102}}, la «edad cerebral» en Fabry y en la gangliosidosis GM1 {{38520360,42410243}}, el movimiento del diafragma en Pompe {{35829785,41756255}}, los pedicelos en la nefropatía de Fabry {{37774924}} y la vacuolización linfocitaria en la enfermedad CLN3 {{33728252}}.',
    'El uso diagnóstico está menos desarrollado. En la enfermedad de Fabry, una red entrenada con cine-resonancia cardíaca la distinguió de la miocardiopatía hipertrófica con un AUC de 0,91, que fue de 0,92 en 31 estudios de otro hospital con otro equipo {{38706878}}. Un sistema de patología digital que detecta podocitos espumosos identificó en un centro externo los siete casos de Fabry, aunque con una especificidad de 0,38 {{41526641}}. En la enfermedad de Pompe, un modelo entrenado con resonancias musculares de 34 centros acertó entre el 70 % y el 80 % de los 116 pacientes incluidos {{40275674}}, y en la aspartilglucosaminuria un clasificador distinguió a 22 pacientes de 24 controles a partir de la resonancia cerebral {{36358448}}.',
    'No se ha encontrado ningún estudio original de electrocardiograma con IA en la enfermedad de Fabry. La referencia es la amiloidosis cardíaca, donde un modelo alcanzó un AUC de 0,91 {{34218880}} y otro se evaluó en un ensayo no aleatorizado que confirmó la enfermedad en 24 de 50 pacientes cribados {{41213043}}. Es el tipo de estudio que falta en las EDL.',
 ]),
 ('Genética, biomarcadores y ómicas', [
    'La interpretación de variantes de significado incierto es un problema cotidiano en las EDL. En la MPS III, un modelo que combina ocho predictores clasificó las variantes con un AUC de 0,91, algo superior al de AlphaMissense {{38802532}}. En la leucodistrofia metacromática, en una evaluación ciega de 219 variantes de *ARSA* el mejor resultado lo obtuvo un modelo construido con herramientas estándar, y los métodos de aprendizaje profundo más avanzados aportaron solo una mejora pequeña {{40055237}}. En Fabry, Pompe y Gaucher se ha intentado predecir, a partir de la estructura de la proteína, qué variantes responden a chaperonas {{34529671,40565264}}. Son estudios computacionales, sin validación clínica.',
    'Las herramientas generales exigen cautela: AlphaMissense {{37733863}} falla en las variantes hipomorfas de las distrofias de retina, las que conservan parte de la función {{41492285}}, lo que aconseja prudencia con las variantes de inicio tardío de las EDL. Además, la prevalencia estimada de la enfermedad de Fabry cambia según cómo se clasifiquen ciertas variantes de *GLA* {{38047356}}.',
    'En biomarcadores, los perfiles de glucosaminoglucanos permitieron tipificar las MPS con exactitudes superiores al 90 % {{30903511,36979466}}, y en Fabry se han comunicado modelos casi perfectos a partir de metabolómica {{34575675}} y de espectroscopia infrarroja {{39390597}}. Estas cifras proceden de menos de cien pacientes sin validación externa y deben leerse como señal de posible sobreajuste, no como rendimiento esperable. Salvo el modelo de anticuerpos ya citado, que incluye lyso-Gb3, no se ha encontrado ningún modelo que integre lyso-Gb1 o lyso-Gb3, y ninguno está validado.',
 ]),
 ('Pronóstico, tratamiento y seguimiento', [
    'Los modelos pronósticos son escasos. En el Registro Español de la Enfermedad de Gaucher (358 pacientes), los árboles de decisión relacionaron la esplenectomía y el retraso del tratamiento con las complicaciones óseas {{32962737}}, y un *random forest* identificó la infiltración medular basal y la edad al inicio del tratamiento como predictores de enfermedad ósea avanzada en 131 pacientes {{37250646}}. En la enfermedad de Fabry, un análisis de agrupamiento describió siete trayectorias de función renal en 234 varones {{37061786}}. Son coherentes con la experiencia clínica, pero no se han validado fuera de su cohorte.',
    'Para el seguimiento se han propuesto medidas objetivas: un índice de marcha en la enfermedad de Pompe de inicio tardío {{41803906}}, la detección automática de asincronía respiratoria en el síndrome de Morquio {{34063456}} y la estimación de la función motora gruesa a partir de vídeo en la leucodistrofia metacromática, con un 82 % de acierto en 44 niños de un ensayo clínico {{42606959}}.',
    'La laguna principal es el tratamiento: no se ha encontrado ningún modelo validado de respuesta al tratamiento enzimático sustitutivo o a la reducción de sustrato, ni ensayos registrados de herramientas de IA en Fabry o en Pompe.',
 ]),
 ('Los retos de entrenar modelos de inteligencia artificial en enfermedades raras', [
    'La escasez de estudios sólidos refleja dificultades estructurales, no falta de interés (tabla 2){{T2}}.',
    '**Pocos pacientes y sobreajuste.** Un modelo aprende de ejemplos. Si son pocos, puede memorizar sus particularidades en lugar de aprender el patrón de la enfermedad, como el estudiante que se sabe de memoria los exámenes de otros años y falla ante preguntas nuevas (figura 1B). Los métodos más flexibles pueden necesitar más de diez veces más eventos por variable que la regresión logística {{25532820}}, y con muestras pequeñas la propia validación cruzada da estimaciones sesgadas {{31697686}}. Además, miles de imágenes no equivalen a miles de pacientes: un clasificador de sedimento urinario para Fabry generó 125.000 fragmentos de entrenamiento a partir de las imágenes de un solo paciente {{36186840}}.',
    '**Heterogeneidad.** El diagnóstico no define un grupo homogéneo: la enfermedad de Gaucher muestra una variación fenotípica marcada {{26096741}}, y pacientes con Pompe y el mismo haplotipo tienen cuadros muy distintos {{17210890}}. Un modelo desarrollado en varones con Fabry clásica {{32806627}} no tiene por qué servir en mujeres o en formas tardías.',
    '**Distribución geográfica y demográfica.** Las EDL no se reparten por igual: la MPS II supone el 55 % de las MPS en Japón y el 29 % en Suiza {{28595941}}, y la variante más frecuente de *IDUA* es distinta en Europa y en el norte de África {{29393969}}. Los datos tampoco: las bases usadas en IA clínica proceden sobre todo de Estados Unidos y China {{36812532}}, y la genética se ha estudiado mayoritariamente en europeos {{30901543}}. Una herramienta de reconocimiento facial no propuso la MPS IVA como primera opción en ningún paciente de una muestra colombiana {{37106005}}, y reconocía el síndrome de Down en el 80 % de los pacientes caucásicos y en el 37 % de los africanos {{27925162}}. El modelo también aprende las desigualdades de acceso sanitario: un algoritmo que usaba el gasto como indicador de enfermedad infraestimó la necesidad de los pacientes negros {{31649194}}.',
    '**Desequilibrio de clases.** Cuando hay un enfermo por cada miles de sanos, un modelo puede tener un AUC alto y, aun así, señalar sobre todo a personas sanas. En el estudio de Fabry citado, con un AUC de 0,82, el 1 % de mayor riesgo tenía una prevalencia proyectada de un caso por cada 2.090 personas {{34930374}}. Deben comunicarse el valor predictivo positivo y la curva de precisión-recall {{25738806}}; equilibrar artificialmente los datos distorsiona las probabilidades {{35686364}}.',
    '**Datos fragmentados.** Los pacientes están repartidos entre centros y registros, con captura incompleta {{36244992}} y codificación deficiente de las enfermedades raras {{25887186}}. Los vocabularios comunes ayudan {{37953324,36910590}}. El aprendizaje federado permite que varios hospitales entrenen un modelo conjunto sin reunir los datos de sus pacientes: cada centro entrena con los suyos y comparte solo los ajustes del modelo. Ha funcionado en un tumor cerebral raro con 71 centros {{36470898}}, pero exige armonizar los datos y no elimina las diferencias entre centros {{33015372}}. No se ha encontrado ningún estudio publicado en EDL.',
    '**Validación externa y prospectiva.** Fuera del centro de origen el rendimiento suele caer: ocurrió en el 81 % de 86 algoritmos radiológicos {{35652114}}, y solo el 6 % de 516 estudios de imagen incluía validación externa {{30799571}}. En esta revisión, dos estudios probaron su modelo en otro hospital, con 31 y 15 casos {{38706878,41526641}}, otros dos evaluaron herramientas desarrolladas con otros datos {{41727682,37106005}} y ninguno midió su efecto sobre la atención.',
    '**Calidad y armonización.** Un modelo no puede ser mejor que sus datos. Las diferencias entre equipos de imagen dificultan los estudios multicéntricos {{34531263}}, y en el estudio de anticuerpos en Fabry las diferencias en la medición de lyso-Gb3 impidieron probar el modelo en una cohorte independiente {{32806627}}.',
    'Las guías TRIPOD+AI {{38626948}}, PROBAST+AI {{40127903}}, STARD-AI {{40954311}}, DECIDE-AI {{35584845}} y CONSORT-AI {{32908283}} indican cómo comunicar y evaluar estos estudios. En Europa, un programa con finalidad médica es un producto sanitario {{MDR}} y, cuando incorpora IA, puede quedar clasificado como sistema de alto riesgo {{AIACT}}. Ninguno de los estudios revisados describe una herramienta autorizada como producto sanitario.',
 ]),
 ('Otras aplicaciones prometedoras', [
    'No se ha encontrado ningún estudio original de grandes modelos de lenguaje en pacientes con EDL; solo un editorial que usó la enfermedad de Pompe para ilustrar las «alucinaciones» de ChatGPT {{36811129}}. En las enfermedades raras en general los resultados son dispares. Sobre 5.213 casos publicados, el mejor modelo de lenguaje situó el diagnóstico correcto en primer lugar en el 23,6 %, frente al 35,5 % de una herramienta clásica de priorización {{41735669}}; en cambio, un sistema que combina un modelo de lenguaje con más de 40 herramientas especializadas obtuvo mejores resultados en evaluaciones retrospectivas {{41708847}}. En una revisión sistemática, la mayoría de los estudios eran retrospectivos y de un solo centro {{41990239}}; ya existe una guía para comunicarlos {{39779929}}.',
    'En investigación farmacológica, el aprendizaje automático se ha combinado con el cribado de fármacos en neuronas de cinco niños con MPS IIIA {{42764280}} y con la búsqueda de ligandos en la sialidosis {{33553934}}, con resultados preclínicos. El aumento de datos y los datos sintéticos se usan cada vez más para paliar la escasez de casos {{41283261}}, pero no sustituyen a pacientes nuevos.',
 ]),
]

CONCLUSIONES = [
    '**Qué está demostrado.** La IA puede medir de forma automática y reproducible variables de imagen, como el volumen del bazo, la carga de desmielinización o la edad ósea, y es técnicamente posible encontrar pacientes con Gaucher, Fabry, Pompe o MPS en datos asistenciales. Solo cuatro estudios se han probado con datos externos.',
    '**Qué es prometedor.** La búsqueda de casos en historias clínicas, la patología digital, la resonancia cardíaca y muscular y la interpretación de variantes, siempre que superen una validación externa. Los registros armonizados y el aprendizaje federado son la vía más realista para reunir pacientes suficientes.',
    '**Qué falta.** Validación en otros centros y poblaciones, evaluación prospectiva, pruebas de que estas herramientas mejoran la atención, modelos de respuesta al tratamiento y estudios en las enfermedades más infrecuentes. Faltan también estudios que comuniquen el valor predictivo positivo y la composición de sus cohortes.',
    'Hoy, la IA en las EDL es una herramienta de investigación, más madura para medir que para diagnosticar. Un AUC elevado en una muestra retrospectiva pequeña no basta para llevarla a la consulta: hacen falta colaboración multicéntrica, datos de calidad y la exigencia de pruebas que pedimos a cualquier otra intervención.',
]

